{
  "query": "query { member(id: \"1\") { id fullName email subscriptions { id active plan { id label } } } }"
}

{
  "query": "query { members(first: 25) { edges { cursor node { id email fullName } } pageInfo { hasNextPage endCursor } } }"
}

{
  "query": "mutation { memberCreate(email: \"new.member@example.com\", fullName: \"New Member\") { id email fullName } }"
}

{
  "query": "query { subscription(id: \"1\") { id active status autorenew plan { id label priceCents interval } member { email } } }"
}

{
  "query": "query { subscriptions(first: 25) { edges { node { id active status plan { label } } } pageInfo { hasNextPage endCursor } } }"
}

{
  "query": "query { passes { id name forSale plans { id label priceCents interval } } }"
}

{
  "query": "query { plans { id label priceCents currency interval intervalCount forSale } }"
}

{
  "query": "query { orders(first: 25) { edges { cursor node { id number status totalCents currency member { email } } } pageInfo { hasNextPage endCursor } } }"
}
